    private void btnSaveFeeActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSaveFeeActionPerformed
        // TODO add your handling code here:
    // 1. Get data from fields
    String classLevel = (String) cmbClassLevel.getSelectedItem();
    String term = txtTerm.getText().trim();
    String academicYear = txtAcademicYear.getText().trim();
    String amountStr = txtTotalAmount.getText().trim();

    // 2. Validation
    if (term.isEmpty() || academicYear.isEmpty() || amountStr.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please fill in all fields.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
        return;
    }

    try {
        // 3. Convert amount string to a double
        double amount = Double.parseDouble(amountStr);
        
        if (amount <= 0) {
            javax.swing.JOptionPane.showMessageDialog(this, "Amount must be greater than zero.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            return;
        }

        // 4. Create the feeStructure object
        model.feeStructure newFee = new model.feeStructure();
        newFee.setClassLevel(classLevel);
        newFee.setTerm(term);
        newFee.setAcademicYear(academicYear);
        newFee.setTotalAmount(amount);

        // 5. Save to database
        dao.FeeStructureDao feeDao = new dao.FeeStructureDao();
        feeDao.save(newFee);

        // 6. Success
        javax.swing.JOptionPane.showMessageDialog(this, "Fee structure saved successfully!");
        
        // Clear fields
        txtTerm.setText("");
        txtAcademicYear.setText("");
        txtTotalAmount.setText("");
        cmbClassLevel.setSelectedIndex(0);

    } catch (NumberFormatException e) {
        // Catch if Admin types letters instead of numbers for the amount
        javax.swing.JOptionPane.showMessageDialog(this, "Please enter a valid number for the amount.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }    
    }//GEN-LAST:event_btnSaveFeeActionPerformed

